extension Int {
    var squared: Int { self * self }
}
let num = 7
print(num.squared)

struct Point {
    var x: Int
    var y: Int
}
extension Point {
    init(origin: Int) {
        self.init(x: origin, y: origin)
    }
}
let p1 = Point(x: 3, y: 4)
let p2 = Point(origin: 5)
print("\(p1.x + p2.x)")

extension String {
    func repeated(_ times: Int) -> String {
        String(repeating: self, count: times)
    }
}
print("Hi".repeated(3))

protocol Greetable {
    func greeting() -> String
}
extension Greetable {
    func greeting() -> String { "Welcome!" }
}
struct Robot: Greetable {}
let r = Robot()
print(r.greeting())

protocol Greeter {
    func greet() -> String
}
extension Greeter {
    func greet() -> String { "Hello from protocol" }
}
struct Person: Greeter {
    func greet() -> String { "Hello from Person" }
}
let g: any Greeter = Person()
print(g.greet())

extension Double {
    var half: Double { self / 2.0 }
}
let val = 10.0.half
print(val)

struct Size {
    var width: Int
    var height: Int
}
extension Size {
    var area: Int { width * height }
}
let s = Size(width: 6, height: 7)
print(s.area)

extension Array {
    var isNotEmpty: Bool { !isEmpty }
}
let list = [1, 2, 3]
print(list.isNotEmpty)

